<?php
require_once dirname(__DIR__).'/includes/auth.php';$u=require_role('supervisor');
$status=(string)($_GET['status']??'');$where=['ps.supervisor_id=?','ps.ended_at IS NULL'];$params=[(int)$u['id']];
if(in_array($status,['submitted','resubmitted','approved','correction_required','rejected'],true)){$where[]='s.status=?';$params[]=$status;}
$sql='SELECT s.id submission_id,s.document_type,s.status,p.id project_id,p.reference_no,p.title,st.first_name,st.last_name,st.matric_number,v.id version_id,v.version_number,v.original_filename,v.uploaded_at FROM submissions s JOIN projects p ON p.id=s.project_id JOIN project_supervisors ps ON ps.project_id=p.id JOIN users st ON st.id=s.student_id JOIN submission_versions v ON v.submission_id=s.id AND v.version_number=s.current_version WHERE '.implode(' AND ',$where).' ORDER BY v.uploaded_at DESC';$q=db()->prepare($sql);$q->execute($params);$rows=$q->fetchAll();
$pageTitle='Submission Review Queue';$crumbTrail=['Submissions'];require dirname(__DIR__).'/includes/header.php';
?>
<section class="card filter-bar mb-3"><form method="get" class="filter-form"><label class="search-box"><?= ui_icon('search') ?><input type="search" class="form-control" placeholder="Search students or documents..." aria-label="Search submissions" data-live-filter="#queueTable tbody tr"></label><div class="filter-selects"><select class="form-select" name="status" id="status" aria-label="Review status" data-autosubmit><option value="">All statuses</option><?php foreach(['submitted','resubmitted','approved','correction_required','rejected'] as $s): ?><option value="<?= e($s) ?>" <?= $status===$s?'selected':'' ?>><?= e(ui_label($s)) ?></option><?php endforeach; ?></select></div><noscript><button class="btn btn-primary btn-sm">Filter</button></noscript></form></section>
<section class="card p-4"><div class="section-row mb-3"><h2 class="section-heading mb-0">Assigned Project Submissions</h2><span class="text-muted small"><?= count($rows) ?> current versions</span></div><div class="table-responsive"><table class="table table-soft" id="queueTable"><thead><tr><th>Student</th><th>Document</th><th>Version</th><th>Submitted</th><th>Status</th><th class="text-end">Action</th></tr></thead><tbody>
<?php foreach($rows as $r): ?><tr><td><strong><?= e(trim(($r['first_name']??'').' '.($r['last_name']??''))) ?></strong><br><small class="text-muted"><?= e($r['matric_number']) ?></small></td><td><?= e(ui_doc_label($r['document_type'])) ?><br><small class="text-muted"><?= e($r['original_filename']) ?></small></td><td>v<?= (int)$r['version_number'] ?></td><td class="text-muted"><?= e(ui_date($r['uploaded_at'])) ?></td><td><?= ui_pill($r['status']) ?></td><td class="text-end"><a class="view-link" href="<?= e(url('supervisor/reviews.php?project_id='.(int)$r['project_id'])) ?>">Review</a></td></tr><?php endforeach; ?>
<?php if(!$rows): ?><tr><td colspan="6"><div class="empty-state">No submissions match this review filter.</div></td></tr><?php endif; ?></tbody></table></div></section>
<?php require dirname(__DIR__).'/includes/footer.php'; ?>
